import { describe, expect, it } from 'vitest';
import { quotePremium } from './premium.js';

const newcomer = { yearsWithMHPCO: 0 };

/** Base premium of a policy, isolated from customer-wide modifiers and the fee. */
function basePremium(items: unknown[]): number {
  // A long-standing customer's follow-up contract would distort the base; use
  // the raw building blocks instead by cancelling nothing and subtracting the
  // known first-insurance surcharge and fee is fragile — so tests below use
  // quotePremium directly with explicit expectations.
  throw new Error('unused');
}

describe('base premiums per item', () => {
  it.each([
    ['sword', 100],
    ['amulet', 60],
    ['staff', 80],
    ['potion', 40],
  ])('prices a plain %s at base %i G', (type, base) => {
    // newcomer, no previous contract: base + 10% first insurance + 5 G fee
    const expected = Math.ceil(base * 1.1) + 5;
    expect(quotePremium(newcomer, 0, [{ type }])).toBe(expected);
  });

  it('charges 25 G per single component', () => {
    expect(quotePremium(newcomer, 0, [{ type: 'rune' }])).toBe(
      Math.ceil(25 * 1.1) + 5,
    );
  });

  it('charges only the processing fee for an empty item list', () => {
    expect(quotePremium(newcomer, 0, [])).toBe(5);
  });

  it('rejects an unknown item type', () => {
    expect(() => quotePremium(newcomer, 0, [{ type: 'broomstick' }])).toThrow();
  });
});

